struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float4 PSMain(VSOut i) : SV_Target
{
    float2 mouse = float2(mouse_x / max(1.0, resolution_x), mouse_y / max(1.0, resolution_y));
    float zoom = 2.5 - mouse.y * 2.0;
    float2 center = float2(-0.5 + (mouse.x - 0.5) * 1.0, (mouse.y - 0.5) * 0.5);
    float2 uv = (i.uv - 0.5) * zoom + center;
    float aspect = resolution_x / max(1.0, resolution_y);
    uv.x *= aspect;
    float2 z = float2(0.0, 0.0);
    float2 c = uv;
    int maxIter = 128;
    int iter = 0;
    for (int k = 0; k < maxIter; k++) {
        float x2 = z.x * z.x - z.y * z.y + c.x;
        float y2 = 2.0 * z.x * z.y + c.y;
        z = float2(x2, y2);
        if (dot(z, z) > 4.0) break;
        iter++;
    }
    if (iter >= maxIter) return float4(0, 0, 0, 1);
    float t = (float)iter / (float)maxIter;
    float3 col;
    col.r = 0.5 + 0.5 * cos(3.0 + t * 15.0);
    col.g = 0.5 + 0.5 * cos(3.0 + t * 15.0 + 0.6);
    col.b = 0.5 + 0.5 * cos(3.0 + t * 15.0 + 1.0);
    return float4(col, 1.0);
}
